if (mode === "shot") { sel.value = "global_999_pdop"; sel.dispatchEvent(new Event("change")); document.querySelector('.why[data-week="1007"]').dispatchEvent(new FocusEvent("focusin",{bubbles:true})); }
else document.getElementById("out").textContent = out.join("\n\n");
document.body.dataset.done = "1";
</script></body></html>
